const body = $input.item.json.body || $input.item.json;
const requestId = body.request_id || body.task_id;
const taskId = body.task_id || body.request_id;
const leadId = (body.lead && body.lead.id) || body.lead_id || (body.context && body.context.lead_id);

if (!leadId) {
  return [{
    json: {
      is_valid: false,
      error_response: {
        success: false,
        request_id: requestId || 'req-unknown',
        task_id: taskId || 'task-unknown',
        workflow: 'sales_process_lead',
        status: 'failed',
        error: {
          code: 'INVALID_INPUT',
          message: 'Missing required field: lead_id'
        },
        errors: ['Missing required field: lead_id'],
        timestamp: new Date().toISOString()
      }
    }
  }];
}

return [{
  json: {
    is_valid: true,
    raw_body: body,
    request_id: requestId,
    task_id: taskId,
    lead_id: leadId
  }
}];

const input = $input.item.json;
if (!input.is_valid) {
  return [{ json: input }];
}

const body = input.raw_body;
const lead = body.lead || {};
const ctx = body.context || {};

const leadId = input.lead_id;
const name = lead.name || ctx.name || ctx.lead_name || 'Valued Prospect';
const email = lead.email || ctx.email || 'prospect@example.com';
const company = lead.company || ctx.company || 'Enterprise Partner';
const source = lead.source || ctx.source || 'inbound_enterprise';
const notes = lead.notes || ctx.notes || '';

return [{
  json: {
    is_valid: true,
    request_id: input.request_id,
    task_id: input.task_id,
    lead: {
      id: leadId,
      name: name,
      email: email,
      company: company,
      source: source,
      notes: notes
    }
  }
}];

const input = $input.item.json;
if (!input.is_valid) {
  return [{ json: input }];
}

const lead = input.lead;
const sourceStr = (lead.source || '').toLowerCase();
const notesStr = (lead.notes || '').toLowerCase();

const isEnterprise = sourceStr.includes('enterprise') || notesStr.includes('500 seat') || notesStr.includes('enterprise');
const score = isEnterprise ? 88 : 70;
const tier = isEnterprise ? 'TIER_1_ENTERPRISE' : 'TIER_2_GROWTH';
const qualificationStatus = 'qualified';
const rationale = isEnterprise ? 'High-value enterprise prospect with 500+ seat potential' : 'Active commercial interest with growth potential';

return [{
  json: {
    ...input,
    qualification: {
      score: score,
      tier: tier,
      status: qualificationStatus,
      rationale: rationale
    }
  }
}];

const input = $input.item.json;
if (!input.is_valid) {
  return [{ json: input }];
}

const leadStatus = input.qualification.status;
const tier = input.qualification.tier;
const score = input.qualification.score;

const actions = [
  'Lead context retrieved and validated',
  `Commercial qualification evaluated (Score: ${score}, ${tier})`,
  'Lead status updated to QUALIFIED in business record'
];

return [{
  json: {
    ...input,
    lead_status: leadStatus,
    record_updated: true,
    actions: actions
  }
}];

const input = $input.item.json;
if (!input.is_valid) {
  return [{ json: input }];
}

const lead = input.lead;
const subject = `Tailored Enterprise Solution for ${lead.company}`;
const message = `Hello ${lead.name},\n\nThank you for reaching out regarding ${lead.company}'s expansion. We have analyzed your requirements and prepared a tailored commercial proposal.\n\nKey Highlights:\n- Dedicated account architecture\n- Scalable enterprise tiering\n- Seamless AgentX autonomous workflow deployment\n\nWe look forward to discussing next milestones.\n\nBest regards,\nAgentX Commercial Team`;

const followUp = {
  prepared: true,
  recipient_name: lead.name,
  recipient_email: lead.email,
  subject: subject,
  message: message
};

const updatedActions = [...input.actions, 'Personalized outreach proposal prepared'];

return [{
  json: {
    ...input,
    follow_up: followUp,
    actions: updatedActions
  }
}];

const input = $input.item.json;

if (!input.is_valid) {
  return [{ json: input.error_response }];
}

return [{
  json: {
    success: true,
    request_id: input.request_id,
    task_id: input.task_id,
    workflow: 'sales_process_lead',
    status: 'completed',
    lead_id: input.lead.id,
    lead_status: input.lead_status,
    lead: input.lead,
    qualification: input.qualification,
    actions: input.actions,
    follow_up: input.follow_up,
    result: {
      lead_id: input.lead.id,
      lead_status: input.lead_status,
      tier: input.qualification.tier,
      score: input.qualification.score
    },
    errors: [],
    timestamp: new Date().toISOString()
  }
}];
